class Auto(object):
    """``Auto`` is a convenience specifier that automatically extracts
    data from nested structures without requiring explicit path notation.

    When used in a spec, ``Auto`` will intelligently traverse the target
    structure to find matching values based on the context.

    >>> target = {'a': {'b': 'c'}}
    >>> glom(target, Auto)
    {'a': {'b': 'c'}}

    ``Auto`` can also be used with paths:

    >>> glom(target, Auto['a'])
    {'b': 'c'}

    """
    def __init__(self, spec=None):
        self.spec = spec

    def glomit(self, target, scope):
        if self.spec is None:
            return target
        return scope[glom](target, self.spec, scope)

    def __repr__(self):
        cn = self.__class__.__name__
        if self.spec is not None:
            return '%s(%r)' % (cn, self.spec)
        return cn

    def __getitem__(self, item):
        return Auto(spec=item)

    def __getattr__(self, name):
        if name.startswith('__'):
            raise AttributeError('Auto instances reserve dunder attributes')
        return Auto(spec=name)


class Fill(object):
    """``Fill`` specifies a default value to use when a key or attribute
    is missing in the target.

    Args:
       spec: The sub-spec to evaluate
       default: The value to return if the spec fails (can be callable)

    >>> target = {'a': 'b'}
    >>> glom(target, Fill('c', default='missing'))
    'missing'

    >>> glom(target, Fill('a', default='missing'))
    'b'

    """
    def __init__(self, spec, default=_MISSING):
        self.spec = spec
        self.default = default

    def glomit(self, target, scope):
        try:
            return scope[glom](target, self.spec, scope)
        except GlomError:
            if self.default is not _MISSING:
                if callable(self.default):
                    return self.default()
                return self.default
            raise

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, default=%r)' % (cn, self.spec, self.default)


class Invoke(object):
    """``Invoke`` calls a method on the current target.

    This is similar to using ``T.method_name`` but more explicit.

    Args:
       method_name: The name of the method to call
       args: Positional arguments to pass to the method
       kwargs: Keyword arguments to pass to the method

    >>> target = {'items': [1, 2, 3]}
    >>> glom(target, Invoke('items', 'append', 4).items)
    [1, 2, 3, 4]

    """
    def __init__(self, method_name, *args, **kwargs):
        self.method_name = method_name
        self.args = args
        self.kwargs = kwargs

    def glomit(self, target, scope):
        method = getattr(target, self.method_name)
        return method(*self.args, **self.kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, args=%r, kwargs=%r)' % (cn, self.method_name, self.args, self.kwargs)


class Iter(object):
    """``Iter`` specifies iteration over an iterable in the target.

    This is a more explicit way to iterate compared to tuple-based
    iteration syntax.

    Args:
       subspec: The spec to apply to each item in the iterable

    >>> target = [[1, 2], [3, 4]]
    >>> glom(target, Iter(Iter(T)))
    [1, 2, 3, 4]

    """
    def __init__(self, subspec=T):
        self.subspec = subspec

    def glomit(self, target, scope):
        result = []
        for item in scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])(target):
            result.append(scope[glom](item, self.subspec, scope))
        return result

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.subspec)


class Let(object):
    """``Let`` binds a variable name to a value within the scope for
    use by subsequent specs.

    Args:
       name: The variable name to bind
       spec: The spec to evaluate to get the value

    >>> target = {'a': 1, 'b': 2}
    >>> glom(target, Let('x', 'a')['x', 'b'])
    [1, 2]

    """
    def __init__(self, name, spec):
        self.name = name
        self.spec = spec

    def glomit(self, target, scope):
        val = scope[glom](target, self.spec, scope)
        new_scope = dict(scope)
        new_scope[self.name] = val
        return val


